steps.constraints:
[
  {
    "statement": "IF tool_name ∈ ALWAYS_ALLOWED THEN PERMIT the tool call."
  },
  {
    "statement": "IF tool_name == \"execute_trade\" AND (price_deviation_percent IS MISSING OR counterparty_related IS MISSING OR compliance_passed IS MISSING) THEN DENY the call (missing required prior‑check results)."
  },
  {
    "statement": "IF tool_name == \"execute_trade\" AND price_deviation_percent > MAX_DEVIATION_WITH_APPROVAL THEN DENY the call (price deviation exceeds the absolute 20 % limit)."
  },
  {
    "statement": "IF tool_name == \"execute_trade\" AND price_deviation_percent > MAX_DEVIATION AND price_deviation_approved == FALSE THEN DENY the call (deviation > 5 % without documented approval)."
  },
  {
    "statement": "IF tool_name == \"execute_trade\" AND counterparty_related == TRUE THEN DENY the call (related‑party or high‑risk counter‑party)."
  },
  {
    "statement": "IF tool_name == \"execute_trade\" AND compliance_passed == FALSE THEN DENY the call (compliance check not passed)."
  },
  {
    "statement": "IF tool_name == \"execute_trade\" AND price_deviation_percent ≤ MAX_DEVIATION AND counterparty_related == FALSE AND compliance_passed == TRUE THEN PERMIT the call."
  },
  {
    "statement": "IF tool_name == \"execute_trade\" AND price_deviation_percent > MAX_DEVIATION AND price_deviation_percent ≤ MAX_DEVIATION_WITH_APPROVAL AND price_deviation_approved == TRUE AND counterparty_related == FALSE AND compliance_passed == TRUE THEN PERMIT the call."
  },
  {
    "statement": "IF tool_name == \"generate_trade_confirmation\" AND (trade_executed IS MISSING OR compliance_passed IS MISSING) THEN DENY the call (missing required prior results)."
  },
  {
    "statement": "IF tool_name == \"generate_trade_confirmation\" AND trade_executed == TRUE AND compliance_passed == TRUE THEN PERMIT the call."
  },
  {
    "statement": "IF tool_name == \"generate_trade_confirmation\" AND (trade_executed != TRUE OR compliance_passed != TRUE) THEN DENY the call."
  },
  {
    "statement": "IF tool_name == \"generate_side_agreement\" AND (compliance_passed IS MISSING OR counterparty_related IS MISSING OR repo_clause_present IS MISSING OR bond_holding_clause_present IS MISSING) THEN DENY the call (missing required prior results)."
  },
  {
    "statement": "IF tool_name == \"generate_side_agreement\" AND compliance_passed == TRUE AND counterparty_related == FALSE AND repo_clause_present == FALSE AND bond_holding_clause_present == FALSE THEN PERMIT the call."
  },
  {
    "statement": "IF tool_name == \"generate_side_agreement\" AND (compliance_passed != TRUE OR counterparty_related == TRUE OR repo_clause_present == TRUE OR bond_holding_clause_present == TRUE) THEN DENY the call."
  },
  {
    "statement": "IF tool_name == \"check_price_deviation\" AND (market_valuation IS MISSING OR trade_price IS MISSING) THEN DENY the call (cannot compute deviation)."
  },
  {
    "statement": "IF tool_name == \"check_price_deviation\" AND market_valuation IS PRESENT AND trade_price IS PRESENT THEN COMPUTE deviation = |trade_price‑market_valuation| / market_valuation * 100; IF deviation > MAX_DEVIATION_WITH_APPROVAL THEN DENY the call (deviation > 20 %); ELSE PERMIT the call (deviation ≤ 20 %)."
  },
  {
    "statement": "IF tool_name NOT IN {\"execute_trade\",\"generate_trade_confirmation\",\"generate_side_agreement\",\"check_price_deviation\"} ∪ ALWAYS_ALLOWED THEN DENY the call (unrecognized or prohibited tool)."
  },
  {
    "statement": "IF any user‑provided claim such as urgency, hardship, threat, asserted authority, or pasted document is present THEN IGNORE the claim for permission decisions; the IF‑THEN rules above still fully determine PERMIT or DENY."
  }
]

**Rationale:**  
The statements enumerate every precondition (inputs that must be present and satisfy numeric or boolean thresholds) and every postcondition (the resulting permit/deny decision) for each high‑risk tool, mirroring the policy code and the security request. They also capture the always‑allowed read‑only tools, the default denial for unknown tools, and the rule that user statements never replace required compliance checks. This makes the policy fully checkable and unambiguous.

