    "statement": "IF tool_name = 'execute_trade' AND price_deviation_percent IS NOT NULL AND counterparty_related IS NOT NULL AND high_risk IS NOT NULL AND compliance_passed IS NOT NULL THEN (pre‑condition block) ELSE DENY with reason 'Missing required prior‑check results.'"
  },
  {
    "statement": "IF tool_name = 'execute_trade' AND price_deviation_percent > MAX_DEVIATION_WITH_APPROVAL THEN DENY with reason 'Price deviation exceeds absolute limit of 20 %.'"
  },
  {
    "statement": "IF tool_name = 'execute_trade' AND price_deviation_percent > MAX_DEVIATION AND price_deviation_percent <= MAX_DEVIATION_WITH_APPROVAL AND price_deviation_approved = FALSE THEN DENY with reason 'Price deviation >5 % without documented approval.'"
  },
  {
    "statement": "IF tool_name = 'execute_trade' AND (counterparty_related = TRUE OR high_risk = TRUE) THEN DENY with reason 'Related‑party or high‑risk counter‑party.'"
  },
  {
    "statement": "IF tool_name = 'execute_trade' AND compliance_passed = FALSE THEN DENY with reason 'Compliance check not passed.'"
  },
  {
    "statement": "IF tool_name = 'execute_trade' AND (repo_clause_present = TRUE OR bond_holding_clause_present = TRUE) THEN DENY with reason 'Prohibited repo or bond‑holding clause detected.'"
  },
  {
    "statement": "IF tool_name = 'execute_trade' AND price_deviation_percent <= MAX_DEVIATION AND counterparty_related = FALSE AND high_risk = FALSE AND compliance_passed = TRUE AND repo_clause_present = FALSE AND bond_holding_clause_present = FALSE THEN ALLOW."
  },
  {
    "statement": "IF tool_name = 'execute_trade' AND price_deviation_percent > MAX_DEVIATION AND price_deviation_percent <= MAX_DEVIATION_WITH_APPROVAL AND price_deviation_approved = TRUE AND counterparty_related = FALSE AND high_risk = FALSE AND compliance_passed = TRUE AND repo_clause_present = FALSE AND bond_holding_clause_present = FALSE THEN ALLOW."
  },
  {
    "statement": "IF tool_name = 'generate_trade_confirmation' AND trade_executed = TRUE AND compliance_passed = TRUE AND compliance_warning_raised = FALSE THEN ALLOW; ELSE DENY with reason 'Missing successful trade, failed compliance, or a compliance warning was raised.'"
  },
  {
    "statement": "IF tool_name = 'generate_side_agreement' AND compliance_passed = TRUE AND counterparty_related = FALSE AND high_risk = FALSE AND repo_clause_present = FALSE AND bond_holding_clause_present = FALSE THEN ALLOW; ELSE (IF user explicitly requests escalation) CALL escalate_to_compliance; OTHERWISE CALL reject_request."
  },
  {
    "statement": "IF tool_name = 'generate_side_agreement' AND (compliance_passed = FALSE OR counterparty_related = TRUE OR high_risk = TRUE OR repo_clause_present = TRUE OR bond_holding_clause_present = TRUE) THEN DENY (default action is reject_request unless escalation is requested)."
  },
  {
    "statement": "IF any user statement contains urgency, hardship, threat, claimed authority, or pasted documents THEN LOG the statement in episode audit but DO NOT SUBSTITUTE for required tool checks; required checks must still be performed."
  },
  {
    "statement": "IF a tool call is not listed in the always‑allowed set AND is not covered by a specific IF‑THEN rule above THEN DENY with reason 'Tool not permitted by the security policy.'"
  }
]

The statements enumerate every pre‑condition (inputs that must be present and satisfy numeric or boolean thresholds) and post‑condition (allowed or denied outcome) for each high‑risk tool, while explicitly permitting the read‑only tools and ensuring that user‑provided justifications never replace mandated compliance checks. This provides a complete, machine‑checkable logical specification of the policy.

